"use strict";(self.webpackChunkultimatelearning=self.webpackChunkultimatelearning||[]).push([[958],{4958:e=>{e.exports=JSON.parse('{"topic":{"id":"loops","title":"Loops","overviewSimple":"Loops are like a toy train that keeps going around the track until it reaches the station. In Java, loops let you repeat actions multiple times automatically.","overviewTechnical":["Loops in Java allow executing a block of code repeatedly based on a condition.","Java provides three main loop types: for, while, and do-while loops.","The for loop is commonly used when the number of iterations is known beforehand.","The while loop executes as long as a given boolean condition remains true.","The do-while loop guarantees at least one execution since the condition is checked after the loop body.","Enhanced for-each loops iterate over arrays or collections without using an index.","Break and continue statements can control the loop\u2019s flow, either exiting early or skipping iterations.","Nested loops enable executing one loop inside another to handle multidimensional data or complex iterations.","Proper loop design helps avoid infinite loops and improves code performance and readability."],"story":"Imagine a toy robot that has to deliver candies to five friends. Instead of walking manually to each friend, the robot repeats the same steps automatically for each friend until all candies are delivered. Loops in Java work the same way, repeating tasks efficiently.","realWorldAnalogy":"Loops are like washing machines on a cycle \u2014 they repeat the same washing process until the clothes are clean, similar to how code executes repeatedly until a condition is met.","keyPoints":["for loop executes a block of code for a fixed number of times","while loop executes based on a condition","do-while loop executes at least once and then checks the condition","Enhanced for-each loop simplifies iteration over arrays and collections","Break exits a loop prematurely","Continue skips the current iteration and moves to the next","Nested loops allow complex iteration structures"],"exampleSimple":"for(int i = 0; i < 5; i++) {\\n    System.out.println(i);\\n}\\n\\nint j = 0;\\nwhile(j < 3) {\\n    System.out.println(j);\\n    j++;\\n}\\n\\nint k = 0;\\ndo {\\n    System.out.println(k);\\n    k++;\\n} while(k < 2);","exampleTechnical":["public class LoopDemo {\\n    public static void main(String[] args) {\\n        // For loop\\n        for(int i = 1; i <= 5; i++) {\\n            System.out.println(\\"For loop iteration: \\" + i);\\n        }\\n\\n        // While loop\\n        int j = 1;\\n        while(j <= 3) {\\n            System.out.println(\\"While loop iteration: \\" + j);\\n            j++;\\n        }\\n\\n        // Do-while loop\\n        int k = 1;\\n        do {\\n            System.out.println(\\"Do-while iteration: \\" + k);\\n            k++;\\n        } while(k <= 2);\\n\\n        // Enhanced for loop\\n        int[] numbers = {10, 20, 30};\\n        for(int num : numbers) {\\n            System.out.println(\\"Enhanced for: \\" + num);\\n        }\\n    }\\n}","public class NestedLoopsDemo {\\n    public static void main(String[] args) {\\n        for(int i = 1; i <= 3; i++) {\\n            for(int j = 1; j <= 2; j++) {\\n                System.out.println(\\"i=\\" + i + \\", j=\\" + j);\\n            }\\n        }\\n    }\\n}"],"extraNotes":["Avoid infinite loops by ensuring the loop condition eventually becomes false.","Use break and continue judiciously to maintain readable code.","Nested loops can increase time complexity; optimize when possible."],"bestPracticesSimple":["Keep loop conditions simple and clear","Use meaningful variable names for counters","Indent properly for readability"],"bestPracticesAdvanced":["Prefer for-each loops for collections and arrays when index is not needed","Minimize nested loops to improve performance","Document complex nested loops for maintainability","Use break/continue carefully to avoid confusing logic","Consider using streams or functional constructs in modern Java for cleaner iterations"]}}')}}]);